/* remove pontilhado dos elementos */
* {outline:none;}

body, html {
	height: 100%;
	background-color:#FFF;
	width:auto;
	font-family: Arial, sans-serif;
	font-style: normal;
	font-weight: normal;
	font-size: 16px;
	color: #4C4C4C;
	overflow: auto;
	-ms-overflow-x:hidden; /* IE 8 */
	overflow-x:hidden;
	margin:auto;
}

#rodape {
	font-size: 14px;
	background-color: #F7F7F7;
	border-top: 1px solid #DDDDDD;
	height: 21px;
	padding-top: 6px;
	padding-left: 20px;
	bottom: 0;
	position:absolute;
	width: 100%;
}
#site { /* Corpo do site */
	width:100%;
	min-height: 100%;
	position: relative;
}
#conteudo{
    clear: both;
    margin: auto;
    max-width: 1024px;
    padding: 10px 0 33px;	
    text-align: justify;
}

#conteudo h1 {text-align:left;}

#banner { /* Banner Acesso */
	margin: 50px auto auto auto;
	width: 600px;
}

img{ /* Fix para borda em img IE*/
	border:none;
}

/* Links */
a:link, a:visited, a.active {
	color: #4a4c4c;	
	text-decoration: none;
}

a:hover {
	color: #43B34B;
	text-decoration: none;
}

/* Cabeçaalho */
.header {
	width: 605px;
	display: block;
	margin: 0 auto 30px auto;
}
#brasao {
	display: inline-block;
	margin: 10px 14px 0 20px;
}

#titulomenor {
	font-size:26px;
	margin-bottom:-18px;
}

.titulo {
	font-family: "Times New Roman", Arial;
	font-size: 70px;
	text-decoration: none;
	color: #333333;
	letter-spacing: 3px;
}
.orgtitulo {
	display: inline-block;
	vertical-align:21px;
} /* FIM CabeÃ§alho */

/* Menu Principal */
#menu {
	color: #4C4C4C;
	font-family: Arial, sans-serif;
	font-size: 16px;
	height: auto;
	text-align: center;
	padding-bottom: 3px;
	border-bottom: 1px solid #dddddd;
}

.menuop {
	color: #4C4C4C;
	display: inline-block;
	height: 24px;
	margin: 0 5px 0 10px;
	cursor: pointer;
}

a.menuop:link {
	color:#4a4c4c;
	text-decoration: none;
}
a.menuop:hover,
a.menuop.ativo {
	color: #43B34B;
	text-decoration: none;
	border-bottom: 4px solid #43B34B;
	-webkit-transition: border-bottom-color 0.3s linear 0s, color 0.3s linear 0s, border-bottom-width 0.1s linear 0s;
	-moz-transition: border-bottom-color 0.3s linear 0s, color 0.3s linear 0s, border-bottom-width 0.1s linear 0s;
	-ms-transition: border-bottom-color 0.3s linear 0s, color 0.3s linear 0s, border-bottom-width 0.1s linear 0s;
	-o-transition: border-bottom-color 0.3s linear 0s, color 0.3s linear 0s, border-bottom-width 0.1s linear 0s;
	transition: border-bottom-color 0.3s linear 0s, color 0.3s linear 0s, border-bottom-width 0.1s linear 0s;
} 

a.menuop:active {
	background-color: #43B34B;
	color: white;
	text-decoration: none;
	-webkit-transition:none;
	
	/*Fix IE transiÃ§Ã£o = 0*/
	-webkit-transition: border-bottom-color 0s linear 0s, color 0s linear 0s, border-bottom-width 0s linear 0s;
	-moz-transition: border-bottom-color 0s linear 0s, color 0s linear 0s, border-bottom-width 0s linear 0s;
	-ms-transition: border-bottom-color 0s linear 0s, color 0s linear 0s, border-bottom-width 0s linear 0s;
	-o-transition: border-bottom-color 0s linear 0s, color 0s linear 0s, border-bottom-width 0s linear 0s;
	transition: border-bottom-color 0s linear 0s, color 0s linear 0s, border-bottom-width 0s linear 0s;
}
/* FIM Menu Principal */

/* Sub Menu Principal */
#submenu {
	display: inline-block;
	float: right;
	height: auto;
	width: 692px;
	text-align: right;
	margin: 10px 0 10px 0;
}
.submenuop {
	display: inline-block;
}

.submenuop a {
	font-size:12px;
	color: #4C4C4C;	
}

.submenuop a:hover{
	opacity:0.7;
}

.icon {
	display: inline-block;
}

.subop {
	font-weight: normal;
	display: inline-block;
	vertical-align: 4px;
	margin-right:13px;
}

/* FIM Sub Menu Principal */

/* Edição de Hoje central */
.edhoje {
	clear: both;
	width: 280px;
	margin-right: auto;
	margin-left: auto;
	margin-bottom: 70px;
}

.edhoje:hover{
	opacity:0.7;
}
a.edhoje:hover{
	/* Fix para 'houver link' ficar com a mesma cor do resto */
	opacity: 1;
}

div.outrosCadernos {
	clear: both;
	max-width: 570px;
	margin: 0 auto 35px;
	text-align: center;
	padding: 0;
}

.pdficon {
	float:left;
	display: inline-block;
	margin-right: 15px;
}

.txthj {
	font-family: Arial, sans-serif;
	font-size: 16px;
	color: #4C4C4C;
	text-decoration: none;
	display: inline-block;
	margin: 17px 0px 0px;
}
.txt-hj-grande {
	font-size: 26px;
	font-weight: bold;
	display: block;
}
.txt-hj-pequeno {
	display: block;
