@import "../fonts/kelson/stylesheet.css";

body {
    font-family: 'Kelson Sans', Arial, sans-serif;
    font-size: 13px;
    text-rendering: optimizeLegibility;
}

#header .navbar-brand {
    background-image: url(../images/Cia_EditoraPE_BRANCA_crop.png);
    /*background-position: 0 -140px;*/
    width: 100%;
    height: 108px;
    background-repeat: no-repeat;
    display: block;
    float: left;
    margin: 20px 200px 20px 0;
    text-indent: -9999px;

}


.collapse-animation {
    transition: max-height 0.5s ease-out;
    height: auto;
    max-height: 600px;
}

.collapse-animation.collapsed {
    overflow: hidden;
    max-height: 0;
}

/*--------------------------------NAVIGATION---------------------------------------*/

.navbar-xs {
    min-height: 22px;
    border-radius: 0;
    border-bottom: 1px solid #404040;
    margin-bottom: 0;
}

.navbar-xs .navbar-nav > li > a {
    border-right: 1px solid #222;
    padding: 5px;
    line-height: 16px
}

.menu-container {
    margin-top: 2px;
    margin-bottom: -15px !important;
    font-size: 19px !important;
    text-transform: uppercase !important;
    color: #ffffff !important;
}

.menu-container a {
    margin-top: 10px;
    font-size: 19px !important;
    text-transform: uppercase !important;
    color: #ffffff !important;
}

#navigation {
    box-sizing: border-box !important;
    -moz-box-sizing: border-box !important;
    -webkit-box-sizing: border-box !important;
}

#navigation .navbar-nav > li > a {

    font-size: 15px;
    padding-top: 50px;
    padding-bottom: 50px;
    text-transform: uppercase;
    border-bottom: 4px solid #e2001a;
    -webkit-transform: perspective(1px) translateZ(0);
    transform: perspective(1px) translateZ(0);
    overflow: hidden;
}

#navigation .navbar-nav > li > a:hover::before, #navigation .navbar-nav > li > a:focus::before, #navigation .navbar-nav > li > a:active::before {
    -webkit-transform: translateY(0);
    transform: translateY(0);
}

#navigation .navbar-nav > li > a::before {
    content: "";
    position: absolute;
    z-index: -1;
    left: 0;
    right: 0;
    bottom: 0;
    background: #e2001a;
    height: 8px;
    -webkit-transform: translateY(8px);
    transform: translateY(8px);
    -webkit-transition-property: transform;
    transition-property: transform;
    -webkit-transition-duration: 0.1s;
    transition-duration: 0.1s;
    -webkit-transition-timing-function: ease-out;
    transition-timing-function: ease-out;
}

.dropdown-menu {
    background-color: #D22323;
    color: #FFF;
}

.dropdown-menu > li > a {
    display: block;
    padding: 0 20px;
    clear: both;
    font-weight: normal;
    font-size: 16px !important;
    color: #FFF;
    white-space: nowrap;
    text-transform: capitalize !important;
    text-align: left;
    -webkit-transition: all .1s ease;
    -moz-transition: all .1s ease;
}

.dropdown-menu > li > a:hover,
.dropdown-menu > li > a:focus {

    background-color: transparent !important;
    color: #000000 !important;
    border-left: 0 !important;

}

.dropdown-toggle {
    background: transparent !important;
}

