/*---------------------------------------------MODAL------------------------------*/
.modal {
    text-align: center;
    padding: 0 !important;
}

.modal:before {
    content: '';
    display: inline-block;
    height: 100%;
    vertical-align: middle;
    margin-right: -4px;
}

.modal-dialog {
    display: inline-block;
    text-align: left;
    vertical-align: middle;
}

.modal-backdrop.in {
    opacity: .7;
    filter: alpha(opacity=70);
}

.modal-twocolors .modal-header {
    padding-left: 70px;
    border-bottom: none;
    text-transform: uppercase;
}

.modal-header .close {
    margin-top: -15px;
    margin-right: -15px;
    padding: 7px 5px;
    background: #FF0000;
}

.close {
    font-size: 60px;
    font-weight: normal;
    line-height: 0.4;
    color: #FFF;
    text-shadow: none;
    opacity: 1;
    filter: alpha(opacity=100);
}

.modal-twocolors .modal-footer {
    padding: 15px;
    text-align: left;
    border-top: none;
}

.modal-twocolors {
    background: -moz-linear-gradient(90deg, #000 33%, #FFF 20%);
